def split_words(raw: str) -> list:
    """Аккуратно делит строку по запятым, не разрывая скобки."""
    out, buf, depth = [], '', 0
    for ch in raw:
        if ch == '(':
            depth += 1
        elif ch == ')':
            depth -= 1
        if ch == ',' and depth == 0:
            if buf.strip():
                out.append(buf.strip())
            buf = ''
        else:
            buf += ch
    if buf.strip():
        out.append(buf.strip())
    return out


def day_words(day: int) -> list:
    return split_words(CORE_DAYS.get(day, ''))
